export function getTranslation(lang: string): Translations {
  if (lang.startsWith("te")) return translations["te-IN"];
  if (lang.startsWith("hi")) return translations["hi-IN"];
  if (lang.startsWith("ta")) return translations["ta-IN"];
  if (lang.startsWith("kn")) return translations["kn-IN"];
  if (lang.startsWith("ml")) return translations["ml-IN"];
  if (lang.startsWith("mr")) return translations["mr-IN"];
  if (lang.startsWith("bn")) return translations["bn-IN"];
  if (lang.startsWith("gu")) return translations["gu-IN"];
  if (lang.startsWith("pa")) return translations["pa-IN"];
  if (lang.startsWith("or")) return translations["or-IN"];
  if (lang.startsWith("as")) return translations["as-IN"];
  if (lang.startsWith("ur")) return translations["ur-IN"];
  return translations["en-IN"];
}
